def valid(number: str) -> bool:
    """Return whether ``number`` is valid according to the Luhn algorithm.

    Digits may be separated by single spaces, which are ignored. Leading,
    trailing, repeated, or otherwise misplaced spaces make the number invalid.
    """
    if not isinstance(number, str) or not number:
        return False

    if number[0] == ' ' or number[-1] == ' ':
        return False

    digits: list[str] = []
    previous_was_space = False

    for character in number:
        if character == ' ':
            if previous_was_space:
                return False
            previous_was_space = True
        elif '0' <= character <= '9':
            digits.append(character)
            previous_was_space = False
        else:
            return False

    if len(digits) < 2:
        return False

    total = 0
    for index, digit in enumerate(reversed(digits)):
        value = int(digit)
        if index % 2 == 1:
            value *= 2
            if value > 9:
                value -= 9
        total += value

    return total % 10 == 0
